// 1. 直接取得 workspace 物件
const workspace = $('When Executed by Another Workflow').first().json;

// 2. 取得 dataflows 陣列
const dataflows = $input.first().json.value;

// 3. 建立 Dataflow 字典
const dataflowDict = {};
for (const item of dataflows) {
  dataflowDict[item.name] = item.objectId;
}

// 4. 分開回傳，產生兩個獨立的 Item
return [
  {
    json: {
    ...workspace,
    ...dataflowDict
    }
  }
];

const items = $input.all();

// 檢查是不是有人 Failed 了
const hasFailed = items.some(item => item.json.Status === 'Failed');

// 檢查是不是全部都 Success 了
const isAllSuccess = items.every(item => item.json.Status === 'Success');

let decision = 'Pending'; // 預設：還有人在跑

if (hasFailed) {
    decision = 'ErrorAlert'; // 發現錯誤，停止並報警
} else if (isAllSuccess) {
    decision = 'AllClear'; // 全員成功，放行
}

return {
    json: {
        decision: decision,
        batch_id: items[0]?.json?.Batch_ID || 'Unknown'
    }
};

// 1. 抓取所有流進這個節點的 Items (不論是從哪一條線進來的)
const allIncomingItems = $input.all();

// 2. 整理成一個 Array 列表
const taskList = allIncomingItems.map(item => {
    return {
        WORKSPACE_ID: item.json.WORKSPACE_ID,
        DATASET_ID: item.json.DATASET_ID
    };
});

// 3. (選擇性) 只提取 ID 變成純字串陣列
const allWorkspaceIds = allIncomingItems.map(i => i.json.WORKSPACE_ID);
const allDatasetIds = allIncomingItems.map(i => i.json.DATASET_ID);

// 4. 回傳給下一個節點，這時會變成「一個 Item 包含一整包清單」
return {
    json: {
        total_tasks: taskList.length,
        tasks: taskList,
        workspace_list: allWorkspaceIds,
        dataset_list: allDatasetIds
    }
};

// 1. 取得所有匯流進來的派發結果
const items = $input.all();

// 2. 自動提取它們的 WORKSPACE_ID 和 DATASET_ID，組裝成清單
const taskList = items.map(item => ({
    workspace_id: item.json.WORKSPACE_ID,
    dataset_id: item.json.DATASET_ID
}));

// 3. 輸出符合你子流程期待的 HelloWorld 物件格式
return {
    json: {
        HelloWorld: {
            task_list: taskList
        }
    }
};

// 1. 取得 API 回傳的第一筆資料 (包含 @odata.context 和 value 陣列)
const inputData = $input.first().json;

// 2. 準備一個空的陣列，用來裝轉換後的新資料
const result = [];

// 3. 確保 value 存在且是個陣列，然後跑迴圈處理每一筆資料
if (inputData.value && Array.isArray(inputData.value)) {

    for (const item of inputData.value) {
        // 把每一筆資料改名，並包裝成 n8n 需要的 json 格式
        result.push({
            json: {
                DATASET_ID: item.targetDataflowId,   // 轉換 Key
                WORKSPACE_ID: item.groupId           // 轉換 Key
            }
        });
    }
}

// 4. 直接輸出這個陣列。
// n8n 會自動把這個陣列變成多個獨立的 Items 流下去！
return result;

// 1. 取得剛剛查完狀態的資料
const items = $input.all();

// 2. 檢查是不是狀態都已經是 Success 或是 Failed 了？
const isAllDone = items.every(item => {
    const status = item.json.STATUS;
    return status === 'Success' || status === 'Failed';
});

// 3. 把判定結果 (true/false) 當作一個「通行證標籤」
for (const item of items) {
    item.json.isAllDone = isAllDone;
}

// 4. 原封不動把資料送給下一關
return items;

// 1. 取得主流程傳進來的完整輸入資料
const inputItem = $('When Executed by Another Workflow').first().json;
const preList = inputItem.PRE_WORKFLOW_LIST;
const result = [];

// 2. 確保有手動輸入前置列表，且它是一個陣列
if (preList && Array.isArray(preList)) {
    for (const preTask of preList) {
        // 3. 把陣列裡的每一筆前置任務抽出來，包裝成 n8n 獨立的 Item
        result.push({
            json: {
                PRE_WORKSPACE_ID: preTask.PRE_WORKSPACE_ID,
                PRE_DATAFLOW_ID: preTask.PRE_DATAFLOW_ID // 💡 這裡幫你對齊圖三的欄位名稱
            }
        });
    }
} else {
    // 安全機制：萬一 Independent 裡面忘記填清單，就當作不需要等，直接放行
    result.push({ json: inputItem });
}

return result;

const result = [];

// 1. 逐一處理從上個節點傳進來的所有資料包 (Items)
for (const item of $input.all()) {
    const data = item.json;

    // 2. 確認這包資料裡面有 'value' 這個陣列
    if (data.value && Array.isArray(data.value)) {
        // 3. 把 value 裡面的每一筆相依性紀錄拉出來，重新組裝
        for (const record of data.value) {
          //4. 篩選這個語意模型要用的前置資料流
            if($('When Executed by Another Workflow').first().json.DATASET_ID == record.datasetObjectId){
              result.push({
                json: {
                    DATASET_ID: record.datasetObjectId,
                    WORKSPACE_ID: record.workspaceObjectId,
                    DATAFLOW_ID: record.dataflowObjectId
                }
              });
            }            
        }
    }
}

// 5. 回傳整理好的陣列。
// 💡 n8n 的魔法：只要你回傳的是 [ {json: ...}, {json: ...} ] 格式，
// 它就會自動幫你把這些資料攤平成「獨立的多個 Items」流下去！
return result;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const inputData = $input.first().json;
var result = [];

if (inputData.value && Array.isArray(inputData.value)) {
    for (const item of inputData.value) {
        // 把每一筆資料改名，並包裝成 n8n 需要的 json 格式
        result.push({
            json: {
                WORKSPACE_NAME: item.name,   // 轉換 Key
                WORKSPACE_ID: item.id           // 轉換 Key
            }
        });
    }
}

// 4. 直接輸出這個陣列。
// n8n 會自動把這個陣列變成多個獨立的 Items 流下去！
return result;

const workspace = $('When Executed by Another Workflow').first().json

// 1. 取得前一個節點回傳的 JSON 資料中的 value 陣列
const dataflows = $input.first().json.value;

// 2. 建立一個空的物件(字典)來存放結果
const result = {};

// 3. 針對陣列中的每一筆資料進行處理
for (const item of dataflows) {
  // 將 name 當作鍵 (Key)，objectId 當作值 (Value) 寫入
  result[item.name] = item.id;
}

// 4. 回傳 n8n 看得懂的格式 (必須包覆在 json 屬性內)
return [
  { 
    json: {
    ...workspace,
    ...result
    }
  }
];

// 1. 取得前一個節點回傳的所有資料陣列
const dataflows = $input.all();

// 2. 建立一個空的物件(字典)來存放結果
const result = {};

// 3. 針對陣列中的每一筆資料進行處理
for (const item of dataflows) {
  // 🚨 關鍵修正：在 n8n 中讀取欄位，中間一定要加 .json
  const name = item.json.WORKSPACE_NAME;
  const id = item.json.WORKSPACE_ID;

  // 將 name 當作鍵 (Key)，objectId 當作值 (Value) 寫入
  if (name && id) {
      result[name] = id;
  }
}

// 4. 回傳 n8n 看得懂的格式
return [{ json: result }];

// 1. 取得主流程傳進來的完整輸入資料
const inputItem = $('When Executed by Another Workflow').first().json;
const preList = inputItem.PRE_WORKFLOW_LIST;
const result = [];

// 2. 確保有手動輸入前置列表，且它是一個陣列
if (preList && Array.isArray(preList)) {
    for (const preTask of preList) {
        // 3. 把陣列裡的每一筆前置任務抽出來，包裝成 n8n 獨立的 Item
        result.push({
            json: {
                PRE_WORKSPACE_ID: preTask.PRE_WORKSPACE_ID,
                PRE_DATAFLOW_ID: preTask.PRE_DATAFLOW_ID // 💡 這裡幫你對齊圖三的欄位名稱
            }
        });
    }
} else {
    // 安全機制：萬一 Independent 裡面忘記填清單，就當作不需要等，直接放行
    result.push({ json: inputItem });
}

return result;

// 把 { 名稱: id, ... } 拆成多個 item，保留名稱與 id
const obj = $input.first().json;

return Object.entries(obj).map(([name, id]) => ({
  json: {
    WORKSPACE_NAME: name,
    WORKSPACE_ID: id,
  }
}));

// 模式：Run Once for All Items
// 取得當前這一圈的 workspace（從 Loop 來源帶過來）
const loopItem = $('Loop Over Items').item.json;

// 兩個並行子流程各自的回傳（本圈資料）
const 資料流程 = $("Call '獲取:所有資料流程'").all().map(i => i.json);
const 語意模型 = $("Call '獲取:所有語意模型'").all().map(i => i.json);

return [{
  json: {
    WORKSPACE_ID: loopItem.WORKSPACE_ID,
    WORKSPACE_NAME: loopItem.WORKSPACE_NAME,
    資料流程,
    語意模型,
  }
}];

// 把所有 workspace 收成以 WORKSPACE_NAME 為 key 的物件
const result = {};
for (const item of $input.all()) {
  const ws = item.json;
  result[ws.WORKSPACE_NAME] = ws;
}

return [{ json: { workspaces: result } }];

const allTasks = $input.all().map(i => i.json);

// 1. 建立雙層字典：statusDict[WORKSPACE_ID][DATASET_ID] = STATUS
const statusDict = {}; 
allTasks.forEach(t => { 
    if (!statusDict[t.WORKSPACE_ID]) {
        statusDict[t.WORKSPACE_ID] = {};
    }
    statusDict[t.WORKSPACE_ID][t.DATASET_ID] = t.STATUS; 
});

const readyToRun = [];
const currentToken = $('Call \'獲取:Fabric Authrozation\'').first().json.access_token;

// 2. 篩選與比對
allTasks.filter(t => t.STATUS === 'NotStarted').forEach(task => {
    let allGreen = true;
    let preList = task.PRE_WORKFLOW_LIST;

    // 🛡️ 階段 A：後包裝與嚴格解析格式
    if (typeof preList === 'string' && preList.trim() !== '') {
        try {
            // 自動修復：將 JSON 字串中「冒號後面、長度大於10的英數連字號」套上雙引號
            let fixedString = preList.replace(/:\s*([a-zA-Z0-9\-]{10,})/g, ':"$1"');
            preList = JSON.parse(fixedString);
        } catch (e) {
            console.error(`[解析失敗] 任務 ${task.DATASET_NAME} 的前置清單格式嚴重錯誤:`, task.PRE_WORKFLOW_LIST);
            // 🚨 絕對不放行！直接亮紅燈擋下，讓它繼續留在 NotStarted 陣營
            allGreen = false; 
        }
    }

    // 🛡️ 階段 B：解析成功後，才開始嚴格的狀態比對
    if (allGreen && preList && Array.isArray(preList)) {
         for (const pre of preList) {
             const preWorkspace = pre.PRE_WORKSPACE_ID;
             const preDataset = pre.PRE_DATAFLOW_ID;

             // 精準使用雙層字典抓取狀態
             const preStatus = statusDict[preWorkspace] ? statusDict[preWorkspace][preDataset] : undefined;

             // 只要前置任務狀態不是 Success，就扣留本任務
             if (preStatus !== 'Success') {
                 allGreen = false; 
                 break; 
             }
         }
    }

    // 3. 綠燈發車：只有格式正確且前置全做完的，才能拿到 Token 準備啟動
    if (allGreen) {
         task.TOKEN = currentToken; 
         readyToRun.push({ json: task });
    }
});

// 4. 防空包彈：避免空陣列導致 n8n 迴圈斷氣
if (readyToRun.length === 0) {
    return [{ json: {} }];
}

return readyToRun;

const allTasks = $input.all().map(i => i.json);
const errors = [];

allTasks.forEach((task, index) => {
    // 取得任務名稱方便報錯辨識
    const taskName = task.DATASET_NAME || `未命名任務_${index}`;

    // 1. 核心必填欄位檢查
    if (!task.WORKSPACE_ID) errors.push(`[${taskName}] 缺少 WORKSPACE_ID`);
    if (!task.DATASET_ID) errors.push(`[${taskName}] 缺少 DATASET_ID`);
    if (task.TYPE !== 'Dataflow' && task.TYPE !== 'Model') {
        errors.push(`[${taskName}] TYPE 必須是 Dataflow 或 Model，當前為: ${task.TYPE}`);
    }

    // 2. 前置清單 (PRE_WORKFLOW_LIST) 格式嚴格檢驗
    let preList = task.PRE_WORKFLOW_LIST;
    if (preList && typeof preList === 'string' && preList.trim() !== '') {
        try {
            // 測試 A：先嘗試常規標準解析
            JSON.parse(preList);
        } catch (e1) {
            try {
                // 測試 B：常規失敗，嘗試用我們的「正規表達式」後包裝修復
                let fixedString = preList.replace(/:\s*([a-zA-Z0-9\-]{10,})/g, ':"$1"');
                JSON.parse(fixedString);
            } catch (e2) {
                // 🚨 測試 C：連後包裝都救不回來，判定為無效格式！
                errors.push(`[${taskName}] 的 PRE_WORKFLOW_LIST 格式嚴重錯誤，無法解析。`);
            }
        }
    }
});

// 3. 結算：只要有 1 個以上的錯誤，直接丟出 Error 中斷整個 n8n 流程！
if (errors.length > 0) {
    throw new Error("🛑 啟動前安檢失敗，請檢查資料庫或設定：\n" + errors.join("\n"));
}

// 4. 安檢全數通過，原封不動將資料往後傳，準備進入大迴圈
return $input.all();

